@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int CurrentStep { get; set; }
    private string ErrorMessage { get; set; } = string.Empty;
    private bool IsSubmitting { get; set; }
    private bool Submitted { get; set; }
    private int SubmittedId { get; set; }

    // Step 1 state
    private string FullName { get; set; } = string.Empty;
    private string Email { get; set; } = string.Empty;
    private string Phone { get; set; } = string.Empty;
    private string Address { get; set; } = string.Empty;

    // Step 2 state
    private List<WorkEntryModel> WorkEntries { get; set; } = new() { new WorkEntryModel() };

    // Step 3 state
    private List<ReferenceModel> References { get; set; } = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4 state
    private string CoverLetter { get; set; } = string.Empty;

    private string GetStepClass(int stepIndex)
    {
        if (stepIndex == CurrentStep) return "active";
        if (stepIndex < CurrentStep) return "completed";
        return "future";
    }

    private bool IsStepClickable(int stepIndex) => stepIndex < CurrentStep;

    private void GoToStep(int stepIndex)
    {
        if (stepIndex < CurrentStep)
        {
            CurrentStep = stepIndex;
            ErrorMessage = string.Empty;
        }
    }

    private async Task NextStep()
    {
        ErrorMessage = string.Empty;

        if (!await ValidateCurrentStep())
            return;

        CurrentStep++;
    }

    private void PreviousStep()
    {
        ErrorMessage = string.Empty;
        if (CurrentStep > 0) CurrentStep--;
    }

    private async Task<bool> ValidateCurrentStep()
    {
        switch (CurrentStep)
        {
            case 0:
                if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email) ||
                    string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
                {
                    ErrorMessage = "All fields are required.";
                    return false;
                }
                var emailValid = await ApplicationService.ValidateEmailAsync(Email);
                if (!emailValid)
                {
                    ErrorMessage = "Please enter a valid email address.";
                    return false;
                }
                return true;

            case 1:
                foreach (var entry in WorkEntries)
                {
                    if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) ||
                        entry.StartDate == null || string.IsNullOrWhiteSpace(entry.Description))
                    {
                        ErrorMessage = "Please complete all required fields for each work entry.";
                        return false;
                    }
                }
                return true;

            case 2:
                foreach (var r in References)
                {
                    if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
                        string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
                    {
                        ErrorMessage = "Please complete all required fields for each reference.";
                        return false;
                    }
                }
                return true;

            case 3:
                if (string.IsNullOrWhiteSpace(CoverLetter))
                {
                    ErrorMessage = "Please write a cover letter.";
                    return false;
                }
                return true;

            default:
                return true;
        }
    }

    private async Task SubmitApplication()
    {
        IsSubmitting = true;
        ErrorMessage = string.Empty;

        try
        {
            var personal = new PersonalInfo(FullName, Email, Phone, Address);
            var workHistory = new WorkHistory(WorkEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate ?? DateTime.MinValue,
                    e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
            var references = References.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
            var application = new JobApplication(personal, workHistory, references, CoverLetter);

            SubmittedId = await ApplicationService.SubmitApplicationAsync(application);
            Submitted = true;
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            IsSubmitting = false;
        }
    }

    // Work entry helpers
    private void AddWorkEntry() => WorkEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(int index)
    {
        if (WorkEntries.Count > 1) WorkEntries.RemoveAt(index);
    }

    private void UpdateWorkEntry(int index, string field, string? value)
    {
        var entry = WorkEntries[index];
        switch (field)
        {
            case nameof(WorkEntryModel.Company): entry.Company = value ?? ""; break;
            case nameof(WorkEntryModel.Title): entry.Title = value ?? ""; break;
            case nameof(WorkEntryModel.Description): entry.Description = value ?? ""; break;
        }
    }

    private void UpdateWorkEntryDate(int index, bool isStart, string? value)
    {
        if (DateTime.TryParse(value, out var date))
        {
            if (isStart) WorkEntries[index].StartDate = date;
            else WorkEntries[index].EndDate = date;
        }
    }

    private void ToggleCurrent(int index, bool isCurrent)
    {
        WorkEntries[index].IsCurrent = isCurrent;
        if (isCurrent) WorkEntries[index].EndDate = null;
    }

    // Reference helpers
    private void AddReference()
    {
        if (References.Count < 3) References.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2) References.RemoveAt(index);
    }

    private void UpdateReference(int index, string field, string? value)
    {
        var r = References[index];
        switch (field)
        {
            case nameof(ReferenceModel.Name): r.Name = value ?? ""; break;
            case nameof(ReferenceModel.Relationship): r.Relationship = value ?? ""; break;
            case nameof(ReferenceModel.Email): r.Email = value ?? ""; break;
            case nameof(ReferenceModel.Phone): r.Phone = value ?? ""; break;
        }
    }

    // Mutable models for form binding
    private class WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime? StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }
}

