+@page "/apply"
+@rendermode InteractiveServer
+@using sv_b9efa3918a78499386c292ea7e8513f9.Models
+@using sv_b9efa3918a78499386c292ea7e8513f9.Services
+@inject IApplicationService ApplicationService
+
+<PageTitle>Job Application</PageTitle>
+
+<h1>Job Application</h1>
+
+<!-- Step Indicator Bar -->
+<nav class="step-indicator" aria-label="Application steps">
+    @for (int i = 0; i < StepNames.Length; i++)
+    {
+        var stepIndex = i;
+        var stepClass = GetStepClass(stepIndex);
+        <button class="step @stepClass"
+                disabled="@(!IsStepClickable(stepIndex))"
+                @onclick="() => GoToStep(stepIndex)">
+            @if (stepIndex < CurrentStep)
+            {
+                <span class="step-icon">&#10003;</span>
+            }
+            else
+            {
+                <span class="step-number">@(stepIndex + 1)</span>
+            }
+            <span class="step-label">@StepNames[stepIndex]</span>
+        </button>
+        @if (i < StepNames.Length - 1)
+        {
+            <span class="step-connector"></span>
+        }
+    }
+</nav>
+
+<!-- Validation / Error Messages -->
+@if (!string.IsNullOrEmpty(ErrorMessage))
+{
+    <div class="alert alert-danger" role="alert">@ErrorMessage</div>
+}
+
+<!-- Step Content -->
+<div class="step-content">
+    @if (Submitted)
+    {
+        <div class="confirmation">
+            <h2>&#10003; Application Submitted!</h2>
+            <p>Your application has been received. Your application ID is <strong>@SubmittedId</strong>.</p>
+        </div>
+    }
+    else if (CurrentStep == 0)
+    {
+        <!-- Step 1: Personal Info -->
+        <h2>Personal Information</h2>
+        <div class="form-group">
+            <label for="fullName">Full Name *</label>
+            <input id="fullName" type="text" @bind="FullName" @bind:event="oninput" />
+        </div>
+        <div class="form-group">
+            <label for="email">Email *</label>
+            <input id="email" type="email" @bind="Email" @bind:event="oninput" />
+        </div>
+        <div class="form-group">
+            <label for="phone">Phone *</label>
+            <input id="phone" type="tel" @bind="Phone" @bind:event="oninput" />
+        </div>
+        <div class="form-group">
+            <label for="address">Address *</label>
+            <input id="address" type="text" @bind="Address" @bind:event="oninput" />
+        </div>
+        <div class="form-actions">
+            <button class="btn btn-primary" @onclick="NextStep">Next</button>
+        </div>
+    }
+    else if (CurrentStep == 1)
+    {
+        <!-- Step 2: Work History -->
+        <h2>Work History</h2>
+        @for (int i = 0; i < WorkEntries.Count; i++)
+        {
+            var index = i;
+            <fieldset class="work-entry">
+                <legend>Position @(index + 1)</legend>
+                <div class="form-group">
+                    <label>Company *</label>
+                    <input type="text" value="@WorkEntries[index].Company"
+                           @onchange="(e) => UpdateWorkEntry(index, nameof(WorkEntryModel.Company), e.Value?.ToString())" />
+                </div>
+                <div class="form-group">
+                    <label>Job Title *</label>
+                    <input type="text" value="@WorkEntries[index].Title"
+                           @onchange="(e) => UpdateWorkEntry(index, nameof(WorkEntryModel.Title), e.Value?.ToString())" />
+                </div>
+                <div class="form-group">
+                    <label>Start Date *</label>
+                    <input type="date" value="@WorkEntries[index].StartDate?.ToString("yyyy-MM-dd")"
+                           @onchange="(e) => UpdateWorkEntryDate(index, true, e.Value?.ToString())" />
+                </div>
+                <div class="form-group form-check">
+                    <input type="checkbox" id="current-@index" checked="@WorkEntries[index].IsCurrent"
+                           @onchange="(e) => ToggleCurrent(index, (bool)(e.Value ?? false))" />
+                    <label for="current-@index">I currently work here</label>
+                </div>
+                @if (!WorkEntries[index].IsCurrent)
+                {
+                    <div class="form-group">
+                        <label>End Date</label>
+                        <input type="date" value="@WorkEntries[index].EndDate?.ToString("yyyy-MM-dd")"
+                               @onchange="(e) => UpdateWorkEntryDate(index, false, e.Value?.ToString())" />
+                    </div>
+                }
+                <div class="form-group">
+                    <label>Description *</label>
+                    <textarea value="@WorkEntries[index].Description"
+                              @onchange="(e) => UpdateWorkEntry(index, nameof(WorkEntryModel.Description), e.Value?.ToString())"></textarea>
+                </div>
+                @if (WorkEntries.Count > 1)
+                {
+                    <button class="btn btn-danger btn-sm" @onclick="() => RemoveWorkEntry(index)">Remove</button>
+                }
+            </fieldset>
+        }
+        <button class="btn btn-secondary" @onclick="AddWorkEntry">Add Another Position</button>
+        <div class="form-actions">
+            <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
+            <button class="btn btn-primary" @onclick="NextStep">Next</button>
+        </div>
+    }
+    else if (CurrentStep == 2)
+    {
+        <!-- Step 3: References -->
+        <h2>References</h2>
+        @for (int i = 0; i < References.Count; i++)
+        {
+            var index = i;
+            <fieldset class="reference-entry">
+                <legend>Reference @(index + 1)</legend>
+                <div class="form-group">
+                    <label>Name *</label>
+                    <input type="text" value="@References[index].Name"
+                           @onchange="(e) => UpdateReference(index, nameof(ReferenceModel.Name), e.Value?.ToString())" />
+                </div>
+                <div class="form-group">
+                    <label>Relationship *</label>
+                    <input type="text" value="@References[index].Relationship"
+                           @onchange="(e) => UpdateReference(index, nameof(ReferenceModel.Relationship), e.Value?.ToString())" />
+                </div>
+                <div class="form-group">
+                    <label>Email *</label>
+                    <input type="email" value="@References[index].Email"
+                           @onchange="(e) => UpdateReference(index, nameof(ReferenceModel.Email), e.Value?.ToString())" />
+                </div>
+                <div class="form-group">
+                    <label>Phone *</label>
+                    <input type="text" value="@References[index].Phone"
+                           @onchange="(e) => UpdateReference(index, nameof(ReferenceModel.Phone), e.Value?.ToString())" />
+                </div>
+                @if (References.Count > 2)
+                {
+                    <button class="btn btn-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
+                }
+            </fieldset>
+        }
+        @if (References.Count < 3)
+        {
+            <button class="btn btn-secondary" @onclick="AddReference">Add Reference</button>
+        }
+        <div class="form-actions">
+            <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
+            <button class="btn btn-primary" @onclick="NextStep">Next</button>
+        </div>
+    }
+    else if (CurrentStep == 3)
+    {
+        <!-- Step 4: Cover Letter -->
+        <h2>Cover Letter</h2>
+        <div class="form-group">
+            <textarea class="cover-letter" @bind="CoverLetter" @bind:event="oninput"
+                      maxlength="2000" rows="12" placeholder="Write your cover letter here..."></textarea>
+            <div class="char-count">@CoverLetter.Length / 2000 characters</div>
+        </div>
+        <div class="form-actions">
+            <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
+            <button class="btn btn-primary" @onclick="NextStep">Next</button>
+        </div>
+    }
+    else if (CurrentStep == 4)
+    {
+        <!-- Step 5: Review & Submit -->
+        <h2>Review &amp; Submit</h2>
+
+        <section class="review-section">
+            <h3>Personal Information <a class="edit-link" @onclick="() => GoToStep(0)">Edit</a></h3>
+            <dl>
+                <dt>Full Name</dt><dd>@FullName</dd>
+                <dt>Email</dt><dd>@Email</dd>
+                <dt>Phone</dt><dd>@Phone</dd>
+                <dt>Address</dt><dd>@Address</dd>
+            </dl>
+        </section>
+
+        <section class="review-section">
+            <h3>Work History <a class="edit-link" @onclick="() => GoToStep(1)">Edit</a></h3>
+            @foreach (var entry in WorkEntries)
+            {
+                <div class="review-item">
+                    <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
+                    @entry.StartDate?.ToString("MMM yyyy") &ndash; @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))<br />
+                    <p>@entry.Description</p>
+                </div>
+            }
+        </section>
+
+        <section class="review-section">
+            <h3>References <a class="edit-link" @onclick="() => GoToStep(2)">Edit</a></h3>
+            @foreach (var r in References)
+            {
+                <div class="review-item">
+                    <strong>@r.Name</strong> (@r.Relationship)<br />
+                    @r.Email &bull; @r.Phone
+                </div>
+            }
+        </section>
+
+        <section class="review-section">
+            <h3>Cover Letter <a class="edit-link" @onclick="() => GoToStep(3)">Edit</a></h3>
+            <p class="cover-letter-preview">@CoverLetter</p>
+        </section>
+
+        <div class="form-actions">
+            <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
+            <button class="btn btn-primary btn-submit" @onclick="SubmitApplication" disabled="@IsSubmitting">
+                @(IsSubmitting ? "Submitting..." : "Submit Application")
+            </button>
+        </div>
+    }
+</div>
+
+@code {
+    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
+
+    private int CurrentStep { get; set; }
+    private string ErrorMessage { get; set; } = string.Empty;
+    private bool IsSubmitting { get; set; }
+    private bool Submitted { get; set; }
+    private int SubmittedId { get; set; }
+
+    // Step 1 state
+    private string FullName { get; set; } = string.Empty;
+    private string Email { get; set; } = string.Empty;
+    private string Phone { get; set; } = string.Empty;
+    private string Address { get; set; } = string.Empty;
+
+    // Step 2 state
+    private List<WorkEntryModel> WorkEntries { get; set; } = new() { new WorkEntryModel() };
+
+    // Step 3 state
+    private List<ReferenceModel> References { get; set; } = new() { new ReferenceModel(), new ReferenceModel() };
+
+    // Step 4 state
+    private string CoverLetter { get; set; } = string.Empty;
+
+    private string GetStepClass(int stepIndex)
+    {
+        if (stepIndex == CurrentStep) return "active";
+        if (stepIndex < CurrentStep) return "completed";
+        return "future";
+    }
+
+    private bool IsStepClickable(int stepIndex) => stepIndex < CurrentStep;
+
+    private void GoToStep(int stepIndex)
+    {
+        if (stepIndex < CurrentStep)
+        {
+            CurrentStep = stepIndex;
+            ErrorMessage = string.Empty;
+        }
+    }
+
+    private async Task NextStep()
+    {
+        ErrorMessage = string.Empty;
+
+        if (!await ValidateCurrentStep())
+            return;
+
+        CurrentStep++;
+    }
+
+    private void PreviousStep()
+    {
+        ErrorMessage = string.Empty;
+        if (CurrentStep > 0) CurrentStep--;
+    }
+
+    private async Task<bool> ValidateCurrentStep()
+    {
+        switch (CurrentStep)
+        {
+            case 0:
+                if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email) ||
+                    string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
+                {
+                    ErrorMessage = "All fields are required.";
+                    return false;
+                }
+                var emailValid = await ApplicationService.ValidateEmailAsync(Email);
+                if (!emailValid)
+                {
+                    ErrorMessage = "Please enter a valid email address.";
+                    return false;
+                }
+                return true;
+
+            case 1:
+                foreach (var entry in WorkEntries)
+                {
+                    if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) ||
+                        entry.StartDate == null || string.IsNullOrWhiteSpace(entry.Description))
+                    {
+                        ErrorMessage = "Please complete all required fields for each work entry.";
+                        return false;
+                    }
+                }
+                return true;
+
+            case 2:
+                foreach (var r in References)
+                {
+                    if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
+                        string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
+                    {
+                        ErrorMessage = "Please complete all required fields for each reference.";
+                        return false;
+                    }
+                }
+                return true;
+
+            case 3:
+                if (string.IsNullOrWhiteSpace(CoverLetter))
+                {
+                    ErrorMessage = "Please write a cover letter.";
+                    return false;
+                }
+                return true;
+
+            default:
+                return true;
+        }
+    }
+
+    private async Task SubmitApplication()
+    {
+        IsSubmitting = true;
+        ErrorMessage = string.Empty;
+
+        try
+        {
+            var personal = new PersonalInfo(FullName, Email, Phone, Address);
+            var workHistory = new WorkHistory(WorkEntries.Select(e =>
+                new WorkEntry(e.Company, e.Title, e.StartDate ?? DateTime.MinValue,
+                    e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
+            var references = References.Select(r =>
+                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
+            var application = new JobApplication(personal, workHistory, references, CoverLetter);
+
+            SubmittedId = await ApplicationService.SubmitApplicationAsync(application);
+            Submitted = true;
+        }
+        catch (Exception ex)
+        {
+            ErrorMessage = $"Submission failed: {ex.Message}";
+        }
+        finally
+        {
+            IsSubmitting = false;
+        }
+    }
+
+    // Work entry helpers
+    private void AddWorkEntry() => WorkEntries.Add(new WorkEntryModel());
+
+    private void RemoveWorkEntry(int index)
