arguments.file_text:
.step-indicator {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 2rem;
    padding: 1rem 0;
    flex-wrap: wrap;
}

.step-indicator .step {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.5rem 1rem;
    border: 2px solid #dee2e6;
    border-radius: 2rem;
    background: #fff;
    cursor: default;
    font-size: 0.9rem;
    transition: all 0.2s;
}

.step-indicator .step.active {
    border-color: #0d6efd;
    background: #0d6efd;
    color: #fff;
    font-weight: 600;
}

.step-indicator .step.completed {
    border-color: #198754;
    background: #d1e7dd;
    color: #198754;
    cursor: pointer;
}

.step-indicator .step.completed:hover {
    background: #a3cfbb;
}

.step-indicator .step.future {
    opacity: 0.5;
}

.step-indicator .step:disabled {
    cursor: default;
}

.step-connector {
    width: 1.5rem;
    height: 2px;
    background: #dee2e6;
}

.step-icon, .step-number {
    font-weight: bold;
}

.step-content {
    max-width: 700px;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.3rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 0.375rem;
    font-size: 1rem;
}

.form-group textarea {
    resize: vertical;
    min-height: 80px;
}

.form-group textarea.cover-letter {
    min-height: 250px;
}

.form-check {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.form-check input[type="checkbox"] {
    width: auto;
}

.form-check label {
    display: inline;
    font-weight: normal;
}

.char-count {
    text-align: right;
    font-size: 0.85rem;
    color: #6c757d;
    margin-top: 0.25rem;
}

.form-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
    padding-top: 1rem;
    border-top: 1px solid #dee2e6;
}

.btn {
    padding: 0.5rem 1.25rem;
    border: none;
    border-radius: 0.375rem;
    font-size: 1rem;
    cursor: pointer;
    transition: background 0.2s;
}

.btn-primary {
    background: #0d6efd;
    color: #fff;
}

.btn-primary:hover {
    background: #0b5ed7;
}

.btn-primary:disabled {
    background: #6c9efc;
    cursor: not-allowed;
}

.btn-outline {
    background: #fff;
    border: 1px solid #6c757d;
    color: #6c757d;
}

.btn-outline:hover {
    background: #f8f9fa;
}

.btn-secondary {
    background: #6c757d;
    color: #fff;
}

.btn-secondary:hover {
    background: #5c636a;
}

.btn-danger {
    background: #dc3545;
    color: #fff;
}

.btn-sm {
    padding: 0.25rem 0.75rem;
    font-size: 0.85rem;
}

.alert {
    padding: 0.75rem 1rem;
    border-radius: 0.375rem;
    margin-bottom: 1rem;
}

.alert-danger {
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

.work-entry, .reference-entry {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1rem;
    margin-bottom: 1rem;
}

.work-entry legend, .reference-entry legend {
    font-weight: 600;
    font-size: 0.95rem;
    padding: 0 0.5rem;
}

.review-section {
    margin-bottom: 1.5rem;
    padding-bottom: 1rem;
    border-bottom: 1px solid #dee2e6;
}

.review-section h3 {
    display: flex;
    align-items: center;
    gap: 1rem;
    font-size: 1.1rem;
}

.edit-link {
    font-size: 0.85rem;
    color: #0d6efd;
    cursor: pointer;
    text-decoration: underline;
}

.review-section dl {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.25rem 1rem;
    margin: 0.5rem 0;
}

.review-section dt {
    font-weight: 500;
    color: #6c757d;
}

.review-item {
    margin: 0.5rem 0;
    padding: 0.5rem;
    background: #f8f9fa;
    border-radius: 0.25rem;
}

.cover-letter-preview {
    white-space: pre-wrap;
